SELECT p.* FROM patient p INNER JOIN `user` u ON p.id = u.id WHERE u.role = 'PATIENT'
AND (LOWER(u.real_name) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR LOWER(u.username) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR u.phone LIKE CONCAT('%', #{keyword}, '%'))
AND p.gender = #{gender}
AND p.allergy_history IS NOT NULL AND TRIM(p.allergy_history) <> ''
AND (p.allergy_history IS NULL OR TRIM(p.allergy_history) = '')
AND u.created_at >= #{startTime}
AND u.created_at <= #{endTime}
ORDER BY u.created_at DESC

